import {useEffect,useRef,useState} from 'react';
import {qwenImageBaseUrl,seedreamImageBaseUrl,seedreamDefaultModel,seedreamFlashModel} from '../../shared/portrait-ai.js';
import {qwenResultHosts} from '../../shared/image-hosts.js';
import {ConnectionFeedback,ConnectionKey} from '../ConnectionFeedback.js';
import {McpPanel} from './McpPanel.js';
import type {LocalTextApi} from '../text-ai/api.js';
type Session=Awaited<ReturnType<LocalTextApi['session']>>;
export function ExternalConnections({api,session,refresh}:{api:LocalTextApi;session:Session|null;refresh:()=>Promise<void>}){
 return <><Connection kind="image" api={api} session={session} refresh={refresh}/><details className="optional-tools"><summary><strong>扩展工具（可选）</strong><span>连接其他工具获取额外信息，不影响简历上传、编辑和下载。</span></summary><Connection kind="mcp" api={api} session={session} refresh={refresh}/><McpPanel api={api} session={session} refresh={refresh}/></details></>;
}
function Connection({kind,api,session,refresh}:{kind:'image'|'mcp';api:LocalTextApi;session:Session|null;refresh:()=>Promise<void>}){
 const info=kind==='image'?session?.imageConnection:session?.mcpConnection;
 const [baseUrl,setBaseUrl]=useState(info?.baseUrl??(kind==='image'?'https://api.openai.com/v1':'')),[model,setModel]=useState(session?.imageConnection?.model??'gpt-image-2'),[busy,setBusy]=useState(false),[message,setMessage]=useState(''),[refreshError,setRefreshError]=useState(''),[multiple,setMultiple]=useState(false),[keyEdited,setKeyEdited]=useState(false);
 const [editing,setEditing]=useState(session?.connections[kind]!=='connected');
 const [provider,setProvider]=useState<string>(()=>imageProvider(session?.imageConnection));
 const [size,setSize]=useState<'1024x1024'|'2048x2048'>(session?.imageConnection?.size??'1024x1024');
 const [resultProxyCompatibility,setResultProxyCompatibility]=useState(session?.imageConnection?.resultProxyCompatibility??false);
 const [proxyCompatibility,setProxyCompatibility]=useState(session?.imageConnection?.proxyCompatibility??false);
 const key=useRef<HTMLInputElement>(null),dirty=useRef(false),job=useRef<{id:string;controller:AbortController;mode:string}|null>(null),alive=useRef(true);
 useEffect(()=>{if(!dirty.current){setBaseUrl(info?.baseUrl??(kind==='image'?'https://api.openai.com/v1':''));if(kind==='image'){setModel(session?.imageConnection?.model??'gpt-image-2');setProvider(current=>current==='custom'&&session?.imageConnection?.provider==='openai'?current:imageProvider(session?.imageConnection));setSize(session?.imageConnection?.size??'1024x1024');setProxyCompatibility(session?.imageConnection?.proxyCompatibility??false);setResultProxyCompatibility(session?.imageConnection?.resultProxyCompatibility??false);}}},[info?.id]);
 useEffect(()=>()=>{alive.current=false;const active=job.current;active?.controller.abort();if(active)void api.write(kind==='image'?'/api/ai/portrait/cancel':'/api/mcp/cancel',{requestId:active.id}).catch(()=>{job.current=null;});},[]);
 async function action(mode:'save'|'test'|'delete'|'retry'|'network'|'capability'|'model'){
  if(job.current)return;
  const active={id:crypto.randomUUID(),controller:new AbortController(),mode};job.current=active;const credentialCheck=kind==='image'&&provider==='seedream'&&(mode==='save'||mode==='test'),deadline=credentialCheck?setTimeout(()=>active.controller.abort(),30000):undefined;setBusy(true);setRefreshError('');setMessage(mode==='delete'?'':kind==='image'?(credentialCheck?'正在验证密钥，不调用生图，最长30秒…':'正在检查照片助手，请稍候…'):'正在连接并查找可用工具…');
  try{
   if(mode==='model'){setMessage('正在切换模型，沿用当前密钥，不调用生图…');if(!info)throw new Error('请先连接方舟服务。');await api.write('/api/connections/image/model',{connectionId:info.id,model:model.trim()},'PATCH',active.controller.signal);dirty.current=false;setModel(model.trim());if(alive.current){setMessage('已切换模型并沿用当前密钥，本次未调用生图；新模型的权限与效果待实际任务验证。');setEditing(false);}}
   if(mode==='network'){const enabled=provider==='qwen'?proxyCompatibility&&resultProxyCompatibility:proxyCompatibility;const raw=await api.write('/api/network/check',{service:provider,vpnCompatibility:enabled},'POST',active.controller.signal) as {vpnCompatibility:boolean};if(alive.current)setMessage(`[NETWORK_VERIFIED] 网络预检查通过，后端VPN兼容${raw.vpnCompatibility?'已开启':'未开启'}。未验证密钥或生成能力，没有调用生图。`);}
   if(mode==='save'){if(kind==='image')setModel(model.trim());const apiKey=key.current?.value??'';if(key.current)key.current.value='';setKeyEdited(false);await api.saveAndVerify(kind,{baseUrl,apiKey,...(kind==='image'?{model:model.trim(),proxyCompatibility,resultProxyCompatibility,provider:provider==='seedream'?'seedream':provider==='qwen'?'qwen':'openai',size}:{})},active.id,multiple,active.controller.signal);dirty.current=false;if(alive.current)setMessage(kind==='image'?(provider==='seedream'?'[VERIFIED] 密钥已验证；生图能力在实际头像任务中验证，本次未调用生图。':'[VERIFIED] 照片助手已连接，可以使用。生成后仍需你核对本人特征。'):'[DISCOVERED] 扩展工具已连接，请在下方选择并授权可用工具。');if(alive.current)setEditing(false);}
   if(mode==='test'){if(!info)throw new Error('请先保存配置。');if(kind==='image'&&provider==='seedream')await api.write('/api/connections/image/auth',{connectionId:info.id,requestId:active.id},'POST',active.controller.signal);else await api.verifyConnection(kind,info.id,active.id,multiple,active.controller.signal);if(alive.current)setMessage(kind==='image'?(provider==='seedream'?'[VERIFIED] 密钥已验证；生图能力在实际头像任务中验证，本次未调用生图。':'[VERIFIED] 照片助手已连接，可以使用。生成后仍需你核对本人特征。'):'[DISCOVERED] 扩展工具已连接，请在下方选择并授权可用工具。');if(alive.current)setEditing(false);}
   if(mode==='capability'){if(!info)throw new Error('请先连接并验证密钥。');await api.write('/api/connections/image/test',{connectionId:info.id,requestId:active.id,multiple,oneProbe:true},'POST',active.controller.signal);if(alive.current)setMessage(`[VERIFIED] ${multiple?'双图参考':'单图编辑'}能力已验证，其他能力没有追加测试。`);}
   if(mode==='retry'){const pending=session?.imageConnection?.pendingDownload;if(!info||!pending)throw new Error('没有可继续下载的图片。');await api.write('/api/connections/image/retry-download',{connectionId:info.id,pendingId:pending.id,requestId:active.id,vpnCompatibility:proxyCompatibility&&resultProxyCompatibility},'POST',active.controller.signal);dirty.current=false;if(alive.current){setMessage('[VERIFIED] 检测图片已下载，未重新生成；可用单图/双图能力以下方状态为准。');setEditing(false);}}
   if(mode==='delete'){if(key.current)key.current.value='';setKeyEdited(false);await api.write(`/api/connections/${kind}`,{},'DELETE',active.controller.signal);dirty.current=false;if(alive.current)setMessage('[DISCONNECTED] 连接已断开，密钥已从本机会话清除。');if(alive.current)setEditing(true);}
  }catch(error){if(alive.current)setMessage(active.controller.signal.aborted?(credentialCheck?'连接验证已取消或超过30秒，本次未调用生图。':'已停止接收；上游可能已受理，不承诺撤销计费。'):error instanceof Error?error.message:'操作失败。');}
  finally{clearTimeout(deadline);if(alive.current){setBusy(false);await refresh().catch(error=>setRefreshError(error instanceof Error?error.message:'读取本机状态失败，请刷新后重试。'));setBusy(false);}if(job.current===active)job.current=null;}
 }
 useEffect(()=>{if(!busy||kind!=='image')return;const timer=setInterval(()=>{void refresh().catch(error=>setRefreshError(error instanceof Error?error.message:'状态刷新失败。'));},1000);return()=>clearInterval(timer);},[busy,kind,refresh]);
 const changed=!!info&&(info.baseUrl!==baseUrl||(kind==='image'&&(session?.imageConnection?.model!==model||(session?.imageConnection?.provider??'openai')!==(provider==='seedream'?'seedream':provider==='qwen'?'qwen':'openai')||(session?.imageConnection?.size??'1024x1024')!==size||resultProxyCompatibility!==Boolean(session?.imageConnection?.resultProxyCompatibility)||proxyCompatibility!==Boolean(session?.imageConnection?.proxyCompatibility)))||keyEdited);
 const retryTargetChanged=!!info&&(info.baseUrl!==baseUrl||session?.imageConnection?.model!==model||(session?.imageConnection?.size??'1024x1024')!==size||(session?.imageConnection?.provider??'openai')!==(provider==='seedream'?'seedream':provider==='qwen'?'qwen':'openai')||keyEdited);
 const state=session?.connections[kind]??(kind==='image'?'unavailable':'disabled');
 const reuseSeedreamKey=kind==='image'&&provider==='seedream'&&session?.imageConnection?.provider==='seedream'&&info?.baseUrl===baseUrl&&(session.imageConnection.size??'1024x1024')===size&&Boolean(session.imageConnection.proxyCompatibility)===proxyCompatibility&&Boolean(session.imageConnection.resultProxyCompatibility)===resultProxyCompatibility&&!keyEdited&&model.trim()!==session.imageConnection.model;
 const status=busy?'正在检查…':changed?'设置有修改，请重新连接':state==='connected'?(kind==='image'?(provider==='seedream'&&session?.imageConnection?.credentialsVerified?'密钥已验证':'已连接，可以使用'):'已连接，工具须授权'):state==='failed'?'连接未成功':state==='configured'?'尚未完成检查':kind==='image'?'尚未连接':'尚未开启';
 return <section className="assistant-card" aria-labelledby={`${kind}-settings-title`}>
   <header className="assistant-card-header"><div><h2 id={`${kind}-settings-title`}>{kind==='image'?'照片助手':'连接扩展工具'}</h2><p>{kind==='image'?'调整头像背景、服装与照片风格，独立于文字助手。':'接入可信工具服务；连接不等于授权使用。'}</p></div><span className="connection-status" data-connected={state==='connected'&&!changed&&!busy}>{status}</span></header>
   <details className="connection-form" open={editing} onToggle={e=>setEditing(e.currentTarget.open)}><summary>{state==='connected'?'更换服务或修改连接':kind==='image'?'设置照片助手':'设置工具连接'}</summary>
   <fieldset disabled={busy}><legend className="settings-sr-only">{kind==='image'?'照片助手连接设置':'扩展工具连接设置'}</legend>
   {kind==='image'?<label>选择图片服务<select value={provider} onChange={e=>{dirty.current=true;setProvider(e.target.value);setProxyCompatibility(false);setResultProxyCompatibility(false);setSize(e.target.value==='seedream'?'2048x2048':'1024x1024');setBaseUrl(e.target.value==='seedream'?seedreamImageBaseUrl:e.target.value==='qwen'?qwenImageBaseUrl:e.target.value==='openai'?'https://api.openai.com/v1':'');setModel(e.target.value==='seedream'?seedreamDefaultModel:e.target.value==='qwen'?'qwen-image-3.0':e.target.value==='openai'?'gpt-image-2':'');}}><option value="openai">OpenAI 图片编辑</option><option value="qwen">千问 图片编辑</option><option value="seedream">豆包 Seedream · 火山方舟</option><option value="custom">其他兼容图片服务（自行填写）</option></select></label>:<label>工具服务地址<input type="url" value={baseUrl} maxLength={2048} placeholder="粘贴工具提供方给你的地址" onChange={e=>{dirty.current=true;setBaseUrl(e.target.value);}}/></label>}
   {kind==='image'&&provider==='qwen'&&<><label>照片效果<select value={model} onChange={e=>{dirty.current=true;setModel(e.target.value);}}><option value="qwen-image-3.0">标准版 · 千问 3.0</option><option value="qwen-image-3.0-pro">精细版 · 千问 3.0 Pro</option></select></label><label>照片清晰度<select value={size} onChange={e=>{dirty.current=true;setSize(e.target.value as typeof size);}}><option value="1024x1024">普通清晰度 · 1024 × 1024</option><option value="2048x2048">高清 · 2048 × 2048（费用可能更高）</option></select></label><p>每次生成一张。精细版请求间隔限制更严格，照片生成后仍需核对本人特征。</p><a className="settings-help-link" href="https://platform.qianwenai.com/docs/api-reference/preparation/api-key" target="_blank" rel="noreferrer">在哪里获取千问密钥 ↗</a><p>请使用千问AI平台的密钥；其他平台或中转服务的密钥可能不通用。</p></>}
   {kind==='image'&&provider==='seedream'&&<><label>Seedream版本<select value={model===seedreamDefaultModel||model===seedreamFlashModel?model:'custom'} onChange={e=>{dirty.current=true;setModel(e.target.value==='custom'?'':e.target.value);}}><option value={seedreamFlashModel}>经济版 · Seedream 5.0 Flash</option><option value={seedreamDefaultModel}>精细版 · Seedream 5.0 Pro</option><option value="custom">自定义模型 / 接入点</option></select></label><p>{model===seedreamFlashModel?'Flash · 速度更快、价格更低':model===seedreamDefaultModel?'Pro · 优先画质':'自定义方舟模型'}。每次一张，约2K清晰度；固定模板保留画幅比例。实际相似度需你确认。</p><p>同一方舟连接只切换模型时，可沿用当前密钥；切换不生图，已保存头像不变。新模型仍须在方舟控制台开通，生图能力单独验证。</p>{model!==seedreamDefaultModel&&model!==seedreamFlashModel&&<label>方舟模型 / 接入点 ID<input value={model} maxLength={100} placeholder={seedreamDefaultModel} onChange={e=>{dirty.current=true;setModel(e.target.value);}}/></label>}<a className="settings-help-link" href="https://console.volcengine.com/ark/" target="_blank" rel="noreferrer">前往方舟获取密钥并开通模型 ↗</a><p>使用方舟API密钥；Endpoint ID需对应Seedream 5.0 Pro或Flash。豆包App账号不能代替API密钥。生成前需在方舟控制台开通对应模型；密钥验证不代表已开通。连接不生图，实际生成可能计费。</p></>}
   {kind==='image'&&provider!=='custom'&&<div><button disabled={busy} onClick={()=>void action('network')}>只检查网络 · 不需要密钥 · 不计费</button><p>使用当前界面的VPN开关直接检查，不保存或读取密钥；结果会说明后端实际使用的兼容状态。</p></div>}
   <ConnectionKey inputRef={key} label={kind==='image'?'连接密钥':'连接密钥（服务方未要求时可留空）'} onChange={()=>{dirty.current=true;setKeyEdited(true);}}/>
   {kind==='image'&&provider==='openai'&&<a className="settings-help-link" href="https://platform.openai.com/api-keys" target="_blank" rel="noreferrer">在哪里获取 OpenAI 密钥 ↗</a>}
   <p className="connection-consent">将连接到：{baseUrl||'尚未填写'}。{kind==='image'?(provider==='seedream'?'连接仅验证网络、密钥与模型目录，最长30秒，不调用生图；模型是否开通及效果在实际任务中验证。':'检查使用系统测试图片，不上传你的照片或简历；可能产生图片费用。'):'只查找工具，不读取简历、不自动授权或执行工具。'}</p>
   {kind==='image'&&<><label className="settings-check"><input type="checkbox" checked={provider==='qwen'?proxyCompatibility&&resultProxyCompatibility:proxyCompatibility} onChange={e=>{dirty.current=true;setProxyCompatibility(e.target.checked);setResultProxyCompatibility(provider==='qwen'&&e.target.checked);}}/>使用本机 VPN／代理兼容模式</label><p>开着 VPN 却连接失败时可尝试；开启即信任本机代理对所选官方接口的路由，千问同时用于已核实的图片下载域名。</p></>}
   <details className="advanced-connection" open={kind==='image'&&provider==='custom'?true:undefined}><summary>其他服务与高级设置</summary>
     {kind==='image'&&<>
     {provider==='custom'&&<><label>服务地址（Base URL）<input type="url" value={baseUrl} maxLength={2048} onChange={e=>{dirty.current=true;setBaseUrl(e.target.value);}}/></label><label>模型名称<input value={model} maxLength={100} onChange={e=>{dirty.current=true;setModel(e.target.value);}}/></label></>}
     <details><summary>技术详情与兼容范围</summary><p>服务地址：{baseUrl}。当前模型：{model}。</p><p>{provider==='seedream'?'豆包使用JSON参考图片接口，返回并解码Base64后才视为检查完成，不追加Images Edits路径。':provider==='qwen'?'千问使用参考照片编辑接口，生成结果下载后才视为检查完成。':'其他兼容服务需支持同步 Images Edits 文件上传和 Base64 返回，系统追加 /images/edits。'}</p><p>开启VPN兼容后信任本机代理的官方域名映射。豆包直接返回Base64图片，仅兼容方舟官方接口。千问同时用于生成接口和已核实的结果图片域名（含加速下载）；仍验证证书和实际连接目标，不允许跳转或其他私网地址。</p><p>API：OpenAI、千问或豆包方舟官方接口。千问结果：{qwenResultHosts.join("、")}。未知结果域名仍需公网DNS。</p></details><label className="settings-check"><input type="checkbox" checked={multiple} onChange={e=>setMultiple(e.target.checked)}/>{provider==='seedream'?'诊断双图参考（一次可能计费请求）':'同时检查“照片＋风格参考图”（最多两次计费请求）'}</label><p>{provider==='seedream'?'仅主动点击下方诊断按钮时测试所选的一种能力，不捆绑生成；最长3分钟。':'默认只检查一次单图编辑；勾选后额外检查双图。单图最长3分钟；双图分两轮，合计最长6分钟。'}检查通过不代表人脸相似度合格。</p>{provider==='seedream'&&<button disabled={!info||changed} onClick={()=>void action('capability')}>测试所选生图能力 · 可能计费</button>}</>}
     {kind==='mcp'&&<p>使用 MCP HTTPS Streamable HTTP，密钥按 Bearer 发送；不支持本机命令（stdio）。只接受明确授权的只读工具。</p>}
   </details>
   <div className="workspace-actions"><button className="primary-button" disabled={kind==='image'&&session?.imageConnection?.pendingDownload?.kind==='test'&&!retryTargetChanged} onClick={()=>void action(reuseSeedreamKey?'model':'save')}>{reuseSeedreamKey?'切换模型 · 沿用当前密钥 · 不生图':kind==='image'?(provider==='seedream'?'连接并验证密钥 · 不生图':'连接并检查 · 可能计费'):'连接并查找工具'}</button><button disabled={!info||changed||(kind==='image'&&session?.imageConnection?.pendingDownload?.kind==='test')} onClick={()=>void action('test')}>{kind==='image'?(provider==='seedream'?'重新验证密钥 · 不生图':'重新检查 · 可能计费'):'重新查找工具'}</button></div>
   </fieldset></details>
   {state==='connected'&&!changed&&<p className="connected-service">当前{kind==='image'?'图片服务':'工具服务'}：{kind==='image'&&provider==='qwen'?`千问 · ${model==='qwen-image-3.0-pro'?'3.0 Pro':'3.0'} · ${size==='2048x2048'?'高清':'普通清晰度'}`:kind==='image'&&provider==='seedream'?`豆包 Seedream · ${model}`:kind==='image'&&provider==='openai'?'OpenAI':baseUrl}</p>}
   {kind==='image'&&session?.imageConnection?.check&&<ol aria-label="照片连接检查进度">{session.imageConnection.check.referenceCount&&<li>{session.imageConnection.check.referenceCount===2?'本轮：双图参考检查':'本轮：单图编辑检查'}</li>}{(['network','generation','download'] as const).map((step,index)=><li key={step}>{['网络可达','图片生成',provider==='seedream'?'图片接收与解码':'图片下载'][index]}：{{idle:'待检查',running:'进行中',passed:'通过',failed:'未通过'}[session.imageConnection!.check![step]]??'待检查'}</li>)}</ol>}
   {kind==='image'&&session?.imageConnection&&<p>已验证能力：单图编辑{session.imageConnection.capabilities.single?'已验证':'未验证'}；双图参考{session.imageConnection.capabilities.multiple?'已验证':'未验证'}。</p>}
   {kind==='image'&&session?.imageConnection?.pendingDownload?.kind==='test'&&<div><p>检测图片已生成，下载链接仅在本机会话保留15分钟。请优先重新下载；只修改VPN选项时无需重填密钥。更换服务或密钥会清除这个待下载结果。</p><button disabled={busy||retryTargetChanged} onClick={()=>void action('retry')}>重新下载检测图片 · 不重新生成</button></div>}
   {info&&<button className="disconnect-button" disabled={busy} onClick={()=>void action('delete')}>{kind==='image'?'断开照片助手':'断开扩展工具'}</button>}
   {busy&&<button onClick={()=>{const active=job.current;active?.controller.abort();if(active)void api.write(kind==='image'?'/api/ai/portrait/cancel':'/api/mcp/cancel',{requestId:active.id}).catch(()=>setMessage('本页已停止接收，但尚未确认服务端取消；不要重复检查。'));}}>停止检查</button>}
   <ConnectionFeedback message={busy&&kind==='image'&&!(provider==='seedream'&&job.current?.mode!=='capability')&&session?.imageConnection?.check?.referenceCount?(provider==='seedream'?`正在测试${multiple?'双图参考':'单图编辑'}，本次仅一次生图请求，请稍候。`:`正在检查${session.imageConnection.check.referenceCount===2?'双图参考':'单图编辑'}（第 ${session.imageConnection.check.referenceCount} / ${multiple?2:1} 项），请稍候；不会自动重复请求。`):message} refreshError={refreshError}/>
 </section>;
}

function imageProvider(connection:Session['imageConnection']){
 if(!connection)return 'openai';
 if(connection.provider==='seedream'||connection.provider==='qwen')return connection.provider;
 return connection.baseUrl==='https://api.openai.com/v1'&&connection.model==='gpt-image-2'?'openai':'custom';
}
